+build_frag_key(websocket_conv_t *websocket_conv, guint32 addr[2], wmem_tree_key_t ws_frag_key[3])
+{
+  addr[0] = (guint64)websocket_conv & 0xffffffff;
+  addr[1] = (((guint64)websocket_conv) >> 32) & 0xffffffff;
+  ws_frag_key[0].length = 2;
+  ws_frag_key[0].key = addr;
+  ws_frag_key[1].length = 1;
+  ws_frag_key[1].key = &websocket_conv->frag_id;
+  ws_frag_key[2].length = 0;
+  ws_frag_key[2].key = NULL;
+}
+
+static void save_first_frag_opcode(websocket_conv_t *websocket_conv, guint8 opcode)
+{
+  uint32 addr[2];
+  wmem_tree_key_t ws_frag_key[3];
+
+  build_frag_key(websocket_conv, addr, ws_frag_key);
+  guint8 *data = wmem_new(wmem_file_scope(), guint8);
+  *data = opcode;
+  wmem_tree_insert32_array(ws_first_frag_opcode_tree, ws_frag_key, data);
+}
+
+static gboolean lookup_first_frag_opcode(websocket_conv_t *websocket_conv, guint8 *opcode)
+{
+  uint32 addr[2];
+  wmem_tree_key_t ws_frag_key[3];
+  guint8 *data;
+
+  build_frag_key(websocket_conv, addr, ws_frag_key);
+  data = (guint8 *)wmem_tree_lookup32_array(ws_first_frag_opcode_tree, ws_frag_key);
+
+  if (!data) {
+    return FALSE;
+  }
+  *opcode = *data;
+  return TRUE;
+}
